const input = $input.first().json;

const question =
  typeof input.question === 'string'
    ? input.question.trim()
    : '';

if (!question) {
  throw new Error(
    'Planner input error: question must be a non-empty string.'
  );
}

const openaiModel =
  typeof input.openaiModel === 'string' && input.openaiModel.trim()
    ? input.openaiModel.trim()
    : 'gpt-5-mini';

return [
  {
    json: {
      question,
      openaiModel,
      languageQuestion: typeof input.languageQuestion === 'string' ? input.languageQuestion.slice(0, 8000) : undefined,
      fallbackLanguage: ['en', 'fr', 'tr'].includes(input.fallbackLanguage) ? input.fallbackLanguage : undefined,
      planFeedback: typeof input.planFeedback === 'string' ? input.planFeedback.slice(0, 500) : '',
    },
  },
];

