// OpenAI Responses API çıktısını doğrula;
// nihai sentez rolleri ile tekrarları kaldır
// ve Planner sözleşmesine dönüştür.

const response = $input.first().json;
const source = $('Validate Planner Input').first().json;

const question = source.question;

// Önceki node'da model taşınıyorsa onu kullan.
// Yoksa varsayılan olarak gpt-5-mini kabul et.
const model =
  source.model ??
  source.openaiModel ??
  'gpt-5-mini';

// OpenAI Responses API içindeki output_text değerini bul.
const content = response?.output
  ?.flatMap((item) => Array.isArray(item?.content) ? item.content : [])
  ?.find((item) => item?.type === 'output_text')
  ?.text;

if (typeof content !== 'string' || !content.trim()) {
  throw new Error(
    'Planner yanıt hatası: OpenAI response.output içinde output_text döndürmedi.'
  );
}

let plan;

try {
  plan = JSON.parse(content);
} catch (error) {
  throw new Error(
    `Planner ayrıştırma hatası: OpenAI geçerli JSON döndürmedi (${error.message}).`
  );
}

const replyLanguage = source.fallbackLanguage
  ? (['en', 'fr', 'tr'].includes(plan.reply_language) ? plan.reply_language : source.fallbackLanguage)
  : undefined;

const directResponse = typeof plan.direct_response === 'string' ? plan.direct_response.trim() : '';
if (!Array.isArray(plan.agents) || (!directResponse && plan.agents.length === 0)) {
  throw new Error(
    'Planner doğrulama hatası: agents boş olmayan bir dizi olmalıdır.'
  );
}

const allowedComplexities = new Set(['low', 'medium', 'high']);

const complexity = allowedComplexities.has(plan.complexity)
  ? plan.complexity
  : null;

if (!complexity) {
  throw new Error(
    'Planner doğrulama hatası: complexity low, medium veya high olmalıdır.'
  );
}

const forbiddenRolePattern =
  /(judge|jüri|hakem|sentez|sentezleyici|rapor yazarı|doküman yazarı|sonuçlandırma|sonuç yazarı|nihai (cevap|yanıt|sonuç)|final (answer|response|report)|baş editör|genel editör|özet uzmanı|sonuç ve |sonuç planlayıcısı|özet ve (?:eylem planı|öneri|önceliklendirme)|eylem planı düzenleyici|öneri ve önceliklendirme|özetleyici|özet[/ ]sonuç|öneri koordinatörü|karar ve yol haritası|yol haritası ve karar)/i;

const forbiddenTaskPattern =
  /(uzman (?:çıktılarını|görüşlerini|yanıtlarını).{0,80}(?:özetle|birleştir|sentezle)|(?:tüm|diğer|önceki) (?:uzman|agent|yanıt|cevap).{0,80}(?:birleştir|sentezle|özetle|önceliklendir)|nihai (cevabı|yanıtı|sonucu|raporu) (yaz|oluştur|hazırla)|final (answer|response|report))/i;

const crossExpertTaskPattern =
  /(?:\b(?:[2-9]|10)|iki|üç|dört|beş|altı|yedi|sekiz|dokuz|on|tüm|bütün|diğer|önceki)\s+(?:bağımsız\s+)?(?:uzman\s+)?(?:değerlendirmeler?[ie]|değerlendirmeye|görüşler?[ie]|görüşe|yanıtlar?[ıa]|yanıta|bulgular?[ıa]|bulguya|uzman(?:ın|ların)\s+(?:değerlendirmelerine|görüşlerine|yanıtlarına|bulgularına))(?:\s+)?(?:dayan|esas al|birleştir|sentezle|özetle|karşılaştır)|(?:en uygun|nihai)\s+(?:genel\s+)?stratejiyi\s+seç.{0,120}(?:yol haritası|bütçe|karar)|(?:yol haritası|bütçe).{0,200}(?:en uygun|nihai)\s+stratejiyi\s+seç/iu;

const genericRolePattern =
  /^(uzman|expert|assistant|agent|analist|genel analist|soruya özel uzman)(\s*\d+)?$/i;

const normalizeText = (value) =>
  value
    .toLocaleLowerCase('tr-TR')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .trim();

const invalidRoleShape = /[.!?\n:;]|(?:^|\s)(?:toparlay\p{L}*|özetleyen|koordinatör\p{L}*|karar uzmanı|koordinasyon ve karar|incele|karşılaştır|hesapla|açıkla|belirle|değerlendir|analiz et|özetle|hazırla|çözümle)(?=\s|$)|(?:ıyor|iyor|uyor|üyor|malı|meli)$/iu;
const planIssues = new Set();
const seenRoles = new Set();
const seenTasks = new Set();
const accepted = [];

for (const candidate of directResponse ? [] : plan.agents) {
  if (accepted.length >= 10) break;

  const role =
    typeof candidate?.role === 'string'
      ? candidate.role.trim()
      : '';

  const task =
    typeof candidate?.task === 'string'
      ? candidate.task.trim()
      : '';

  if (!role || !task || role.length > 64 || role.split(/\s+/).length > 7 || invalidRoleShape.test(role) || normalizeText(role) === normalizeText(task)) {
    planIssues.add('role kısa ve doğal bir uzmanlık unvanı, task ayrı ve somut bir görev olmalı.');
    continue;
  }

  if (
    forbiddenRolePattern.test(role) ||
    forbiddenTaskPattern.test(task) ||
    crossExpertTaskPattern.test(task) ||
    (/^(?:eylem|aksiyon|uygulama) planlama uzmanı$|^(?:action|implementation) planning (?:expert|specialist)$/iu.test(role) || /(?:her(?:\s+bir)?|diğer|önceki|tüm|bütün|başka\s+bir|öteki)\s+(?:(?:bağımsız|görevli)\s+)?(?:uzman|ajan|agent)\p{L}*\s+(?:bulgu|sonuç|yanıt|cevap|çıktı|görüş|öneri|rapor|değerlendirme|çalışma)\p{L}*|(?:all|each|other|previous|fellow)\s+(?:agents?|experts?|specialists?)(?:[\u0027’]s?)?\s+(?:findings|outputs|answers|responses|recommendations|reports|assessments)|(?:uzman|ajan)\p{L}*\s+arasında\s+koordinasyon/iu.test(task)) ||
    genericRolePattern.test(role)
  ) {
    planIssues.add('Genel özet, koordinasyon ve ortak karar rolleri kullanılamaz. Yalnızca konuya özgü bağımsız uzmanlıklar üret.');
    continue;
  }

  const roleKey = normalizeText(role);
  const taskKey = normalizeText(task);

  if (!roleKey || !taskKey) continue;

  if (
    seenRoles.has(roleKey) ||
    seenTasks.has(taskKey)
  ) {
    continue;
  }

  seenRoles.add(roleKey);
  seenTasks.add(taskKey);

  accepted.push({
    role,
    task,
  });
}

if (accepted.length === 0) {
  if (!directResponse && !planIssues.size) planIssues.add('En az bir geçerli, konuya özgü uzman gerekli.');
  accepted.push({
    role: 'Konu Alanı Analisti',
    task:
      directResponse ? 'Kullanıcıya uygulama sınırını veya gerekli açıklama sorusunu kısa ve dürüst biçimde ilet.' :
      'Asıl sorunun doğrudan cevaplanması için gerekli temel olguları, ölçütleri ve belirsizlikleri bağımsız olarak incele.',
  });
}

const agents = accepted.map((agent, index) => ({
  agent_id: index + 1,
  role: agent.role,
  task: agent.task,
}));

const questionType =
  typeof plan.question_type === 'string' &&
  plan.question_type.trim()
    ? plan.question_type.trim()
    : 'genel';

return [
  {
    json: {
      question,
      model,
      questionType,
      replyLanguage,
      complexity,
      agentCount: agents.length,
      agents,
      ...(directResponse ? { directResponse } : {}),
      ...(planIssues.size ? { planIssue: [...planIssues].join(' ') } : {}),
    },
  },
];
